INSERT INTO music_sources (source_id, code, name, source_type, access_method, base_url, license_name, rights_scope, requires_attribution, attribution_text, priority, fallback_source_id, is_enabled, requires_credentials, last_success_at, notes) VALUES
(1, 'MUSE_SEED_CATALOG', 'MUSE seed catalogue', 'MUSIC_METADATA', 'FILE_FEED', NULL, 'Project-authored fictional catalogue (CC0)', 'METADATA,AUDIO_FEATURES', 0, NULL, 90, NULL, 1, 0, '2026-08-27 15:32:25', 'Initial import that created the demo catalogue.'),
(2, 'MUSE_CATALOG_FEED', 'MUSE partner feed (file)', 'MUSIC_METADATA', 'FILE_FEED', 'database/sources', 'Project-authored fictional catalogue (CC0)', 'METADATA,AUDIO_FEATURES', 0, NULL, 20, NULL, 1, 0, NULL, 'JSON feed files with metadata and pre-computed audio analysis. Approved fallback for metadata.'),
(3, 'MUSICBRAINZ', 'MusicBrainz Web Service', 'MUSIC_METADATA', 'API', 'https://musicbrainz.org/ws/2/', 'CC0 1.0 (core data)', 'METADATA', 0, NULL, 10, 2, 0, 0, NULL, 'Metadata only. No audio or artwork rights. Disabled until MUSICBRAINZ_ENABLED=true and MUSICBRAINZ_USER_AGENT (with contact details) are set.'),
(4, 'TMDB', 'The Movie Database', 'MOVIE_METADATA', 'API', 'https://api.themoviedb.org/3/', 'TMDB API Terms of Use', 'METADATA', 1, 'This product uses the TMDB API but is not endorsed or certified by TMDB.', 30, NULL, 0, 1, NULL, 'Film metadata (title, year, overview, link). Disabled until TMDB_ENABLED=true and a token are set. Posters are not stored.'),
(5, 'MUSE_SKETCH', 'Demo sketch (local fixture)', 'PLAYBACK', 'GENERATED', NULL, 'Generated in the browser; no third-party audio', 'AUDIO_PREVIEW', 0, NULL, 50, NULL, 1, 0, NULL, 'DEMO FIXTURE: a short sound synthesised in the browser from the song\'s tempo, key, mode and energy. It is not the recording and not provider data.'),
(6, 'MANUAL_ENTRY', 'Admin entry', 'MUSIC_METADATA', 'MANUAL', NULL, 'Entered by MUSE curators', 'METADATA,AUDIO_FEATURES', 0, NULL, 60, NULL, 1, 0, NULL, 'Songs created by hand in the admin console.'),
(7, 'YOUTUBE_DATA', 'YouTube Data API v3', 'VIDEO_METADATA', 'API', 'https://www.googleapis.com/youtube/v3', 'YouTube API Services Terms of Service', 'METADATA', 1, 'Video links via the YouTube Data API.', 40, NULL, 0, 1, NULL, 'Links to public videos (id, title, channel, URL). Never downloads or extracts audio. Needs YOUTUBE_ENABLED=true and YOUTUBE_API_KEY.'),
(8, 'LOCAL_MEDIA', 'Local media library', 'PLAYBACK', 'USER_UPLOAD', NULL, 'Files supplied by the operator, who holds the rights', 'AUDIO_FULL', 0, NULL, 10, NULL, 1, 0, NULL, 'Audio files you own or are licensed to use, placed in LOCAL_MEDIA_DIR and registered per song by a curator.'),
(9, 'EXTERNAL_PREVIEW', 'Licensed preview provider', 'PLAYBACK', 'API', NULL, 'Per contract with the provider', 'AUDIO_PREVIEW', 1, 'Preview courtesy of the configured provider.', 20, NULL, 0, 1, NULL, 'Vendor-neutral contract (GET /previews?isrc=). Disabled until EXTERNAL_PREVIEW_* settings are present.');
